using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
namespace CodexOutTransfer {
public static class OutGrassEdgeDiagnosis {
const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/";
static void Capture(Camera c,string n){typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+n});}
[MenuItem("Tools/Out Scene Transfer/Diagnose Grass Ridge Edges")]
public static void Run(){var b=new StringBuilder();try{var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var roots=s.GetRootGameObjects();var cam=roots.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");var focus=cam.GetComponent<MeadowCameraFocus>();b.AppendLine("camera="+cam.transform.position+" fov="+cam.fieldOfView+" focus="+focus.EffectiveFocusDistance+" dof="+focus.depthOfField+" focalLength="+focus.focalLength+" aperture="+focus.aperture);var terrain=roots.SelectMany(g=>g.GetComponentsInChildren<Terrain>(false)).First();b.AppendLine("terrain="+terrain.transform.position+" fog="+RenderSettings.fog+" fogMode="+RenderSettings.fogMode);
foreach(var root in roots.Where(g=>g.name.StartsWith("Distant Hill Grass"))){b.AppendLine("coverage="+root.name+" active="+root.activeInHierarchy+" position="+root.transform.position+" scale="+root.transform.lossyScale);foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){var mesh=r.GetComponent<MeshFilter>().sharedMesh;var uv=new List<Vector4>();mesh.GetUVs(0,uv);float min=float.PositiveInfinity,max=float.NegativeInfinity;int samples=0;var v=mesh.vertices;for(int i=0;i<v.Length;i+=Mathf.Max(1,v.Length/40)){var p=r.transform.TransformPoint(v[i]);if(i<uv.Count&&uv[i].w==0){float surface=terrain.SampleHeight(p)+terrain.transform.position.y;float diff=p.y-surface;min=Mathf.Min(min,diff);max=Mathf.Max(max,diff);samples++;}}b.AppendLine("chunk="+r.name+" enabled="+r.enabled+" bounds="+r.bounds+" groundSamples="+samples+" surfaceOffset="+min+".."+max+" shader="+r.sharedMaterial?.shader?.name);}}
Capture(cam,"Out_grass_edges_current.png");bool dof=focus.depthOfField;try{focus.depthOfField=false;focus.Apply();Capture(cam,"Out_grass_edges_without_dof.png");}finally{focus.depthOfField=dof;focus.Apply();}
bool fog=RenderSettings.fog;try{RenderSettings.fog=false;Capture(cam,"Out_grass_edges_without_builtin_fog.png");}finally{RenderSettings.fog=fog;}
b.AppendLine("temporaryComparisonsRestored=True noSceneSave=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_grass_edge_diagnosis.txt",b.ToString());}
}
